import type React from "react";

/** Um arquivo dentro do modo multi-arquivo (`files`) — cada um vira uma aba. */
export interface CodeBlockFile {
  filename: string;
  code: string;
  language?: string;
}

export interface CodeBlockProps {
  /** Código do arquivo único (modo default). Ignorado quando `files` é passado. */
  code?: string;
  language?: string;
  filename?: string;
  /**
   * Modo multi-arquivo — abas trocando entre arquivos diferentes (ex.: tabs.tsx /
   * hooks.ts / api.ts do mesmo exemplo). Quando presente, `code`/`filename`/`language`
   * únicos são ignorados. Origem: shadcndashboard, aprovado em
   * docs/component-import/variant-intake/DECISIONS.md #7 (abas por arquivo — abas por
   * linguagem tipo curl/JS/Python do mesmo conteúdo NÃO entra nesta rodada).
   */
  files?: CodeBlockFile[];
  /** Aba ativa inicial em modo `files` (uncontrolled). @default 0 */
  defaultFileIndex?: number;
  showLineNumbers?: boolean;
  maxHeight?: number;
  className?: string;
  style?: React.CSSProperties;
}

"use client";
import { useState } from "react";

import { Button } from "@/components/ui/cn/button/Button";
import { cn } from "@/lib/utils";

import type { CodeBlockProps } from "./code-block.types";

const CopyIcon = () => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true" className="w-3.5 h-3.5">
    <rect x="9" y="9" width="13" height="13" rx="2" />
    <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" />
  </svg>
);
const CheckIcon = () => (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2.5"
    aria-hidden="true"
    className="w-3.5 h-3.5 text-success"
  >
    <polyline points="20 6 9 17 4 12" />
  </svg>
);

export function CodeBlock({
  code,
  language,
  filename,
  files,
  defaultFileIndex = 0,
  showLineNumbers = false,
  maxHeight,
  className,
  style,
}: CodeBlockProps) {
  const [copied, setCopied] = useState(false);
  const isMultiFile = !!files && files.length > 0;
  const [activeIndex, setActiveIndex] = useState(() =>
    isMultiFile ? Math.min(Math.max(defaultFileIndex, 0), files!.length - 1) : 0
  );
  const activeFile = isMultiFile ? files![activeIndex] : undefined;

  const effectiveCode = activeFile ? activeFile.code : code ?? "";
  const effectiveLanguage = activeFile ? activeFile.language : language;
  const effectiveFilename = activeFile ? activeFile.filename : filename;
  const lines = effectiveCode.split("\n");

  function copy() {
    navigator.clipboard.writeText(effectiveCode).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  }

  return (
    <div
      style={style}
      className={cn(
        // text-body-callout: sem match exato na escala pro tamanho original (13px, entre
        // caption e callout) — alinhado ao mesmo tamanho já usado no TerminalBlock (componente
        // irmão de exibição de código)
        "group relative rounded-(--radius-md) border border-rule bg-graphite overflow-hidden text-body-callout font-mono",
        className
      )}
    >
      {isMultiFile ? (
        <div className="flex items-center justify-between border-b border-rule bg-graphite-2">
          <div role="tablist" aria-label="Arquivos" className="flex items-center overflow-x-auto">
            {files!.map((f, i) => (
              <button
                key={f.filename}
                type="button"
                role="tab"
                aria-selected={i === activeIndex}
                onClick={() => setActiveIndex(i)}
                className={cn(
                  "shrink-0 px-(--spacing-lg) py-(--spacing-sm) text-body-caption font-medium border-b-2 -mb-px transition-colors duration-[120ms]",
                  i === activeIndex
                    ? "text-foreground border-patina"
                    : "text-faint border-transparent hover:text-foreground"
                )}
              >
                {f.filename}
              </button>
            ))}
          </div>
          <Button
            type="button"
            variant="ghost"
            intent="neutral"
            size="xs"
            className="shrink-0 mr-(--spacing-sm)"
            aria-label={copied ? "Copied!" : "Copy code"}
            aria-live="polite"
            onClick={copy}
          >
            {copied ? <CheckIcon /> : <CopyIcon />}
            <span>{copied ? "Copied!" : "Copy"}</span>
          </Button>
        </div>
      ) : (
        (effectiveFilename || effectiveLanguage) && (
          <div className="flex items-center justify-between px-(--spacing-lg) py-(--spacing-sm) border-b border-rule bg-graphite-2">
            <div className="flex items-center gap-(--spacing-sm)">
              {effectiveFilename && (
                <span className="text-body-caption text-foreground font-medium">{effectiveFilename}</span>
              )}
              {effectiveLanguage && !effectiveFilename && (
                <span className="text-body-caption text-faint uppercase tracking-wide">{effectiveLanguage}</span>
              )}
              {effectiveLanguage && effectiveFilename && (
                <span className="text-body-caption text-faint">{effectiveLanguage}</span>
              )}
            </div>
            <Button
              type="button"
              variant="ghost"
              intent="neutral"
              size="xs"
              aria-label={copied ? "Copied!" : "Copy code"}
              aria-live="polite"
              onClick={copy}
            >
              {copied ? <CheckIcon /> : <CopyIcon />}
              <span>{copied ? "Copied!" : "Copy"}</span>
            </Button>
          </div>
        )
      )}

      <div className="relative overflow-auto" style={maxHeight ? { maxHeight } : undefined}>
        {!isMultiFile && !effectiveFilename && !effectiveLanguage && (
          <button
            type="button"
            aria-label={copied ? "Copied!" : "Copy code"}
            aria-live="polite"
            onClick={copy}
            className={cn(
              "absolute top-(--spacing-sm) right-(--spacing-sm) z-10 flex items-center gap-(--spacing-2xs)",
              "opacity-0 group-hover:opacity-100 group-focus-within:opacity-100 focus-visible:opacity-100 transition-opacity",
              "text-faint hover:text-foreground bg-graphite-2 border border-rule rounded-(--radius-sm) px-(--spacing-sm) py-(--spacing-2xs) text-body-caption"
            )}
          >
            {copied ? <CheckIcon /> : <CopyIcon />}
          </button>
        )}
        {/* role="presentation": usado só pra alinhar número da linha com o código, não é
            dado tabular de verdade — sem isso, leitor de tela anunciava "tabela com N linhas"
            pra um simples bloco de código */}
        <table className="w-full border-collapse" role="presentation">
          <tbody>
            {lines.map((line, i) => (
              <tr key={i} className="hover:bg-foreground/[0.03]">
                {showLineNumbers && (
                  <td
                    aria-hidden="true"
                    className="select-none text-right text-faint pr-(--spacing-lg) pl-(--spacing-lg) py-0 leading-6 w-px align-top border-r border-rule"
                  >
                    {i + 1}
                  </td>
                )}
                <td
                  className={cn(
                    "py-0 leading-6 text-foreground",
                    showLineNumbers ? "pl-(--spacing-lg) pr-(--spacing-lg)" : "px-(--spacing-lg)"
                  )}
                >
                  <pre className="m-0 whitespace-pre">{line || " "}</pre>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
